1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID    string `json:"id"`
27		Name  string `json:"name"`
28		Price int64  `json:"price_fen"` // 固定单价，非负整数分，创建后不可修改
29	}
30	
31	type usageRecord struct {
32		ID         string `json:"id"`
33		CustomerID string `json:"customer_id"`
34		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
35		Quantity   int64  `json:"quantity"`
36	}
37	
38	type billLine struct {
39		UsageID  string `json:"usage_id"`
40		Time     string `json:"time"`
41		Quantity int64  `json:"quantity"`
42		LineFee  int64  `json:"line_fee_fen"`
43	}
44	
45	type bill struct {
46		ID         string     `json:"id"`
47		CustomerID string     `json:"customer_id"`
48		Month      string     `json:"month"` // YYYY-MM（UTC）
49		TotalQty   int64      `json:"total_quantity"`
50		UnitPrice  int64      `json:"unit_price_fen"`
51		TotalFee   int64      `json:"total_fee_fen"`
52		Lines      []billLine `json:"lines"`
53		CreatedAt  string     `json:"created_at"`
54	}
55	
56	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
57	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
58	type adjustment struct {
59		ID           string `json:"id"`
60		CustomerID   string `json:"customer_id"`
61		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
62		Amount       int64  `json:"amount_fen"`
63		Reason       string `json:"reason"`
64		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
65		CreatedAt    string `json:"created_at"`
66		Revoked      bool   `json:"revoked"`
67		RevokeReason string `json:"revoke_reason,omitempty"`
68		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
69		RevokedAt    string `json:"revoked_at,omitempty"`
70	}
71	
72	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
73	type paymentAllocation struct {
74		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
75		Amount int64  `json:"amount_fen"` // 正整数分
76	}
77	
78	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
79	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
80	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
81	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
82	type payment struct {
83		ID           string              `json:"id"`
84		CustomerID   string              `json:"customer_id"`
85		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
86		Note         string              `json:"note"`
87		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
88		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
89		CreatedAt    string              `json:"created_at"`
90		Revoked      bool                `json:"revoked"`
91		RevokeReason string              `json:"revoke_reason,omitempty"`
92		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
93		RevokedAt    string              `json:"revoked_at,omitempty"`
94	}
95	
96	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
97	// 读入时归一化为一项分配，之后一律按新格式写回。
98	func (p *payment) UnmarshalJSON(data []byte) error {
99		type plain payment // 去掉方法，避免递归
100		var raw struct {
101			plain
102			Month  string `json:"month"`      // 旧格式：所属账单月份
103			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
104		}
105		if err := json.Unmarshal(data, &raw); err != nil {
106			return err
107		}
108		*p = payment(raw.plain)
109		if len(p.Allocations) == 0 && raw.Month != "" {
110			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
111			p.Total = raw.Amount
112		}
113		return nil
114	}
115	
116	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
117	func (p *payment) amountFor(month string) int64 {
118		for _, al := range p.Allocations {
119			if al.Month == month {
120				return al.Amount
121			}
122		}
123		return 0
124	}
125	
126	type state struct {
127		Version     int                     `json:"version"`
128		Customers   map[string]*customer    `json:"customers"`
129		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
130		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
131		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
132		Payments    map[string]*payment     `json:"payments"`    // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
133		NextSeq     int64                   `json:"next_seq"`    // 已分配的最大操作序号（调整/撤销/收款共用）
134		path        string                  `json:"-"`
135	}
136	
137	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
138	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
139	func loadStore(dir string) (*state, error) {
140		p := filepath.Join(dir, "state.json")
141		data, err := os.ReadFile(p)
142		if err != nil {
143			if errors.Is(err, os.ErrNotExist) {
144				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
145					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
146				}
147				return newState(p), nil
148			}
149			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
150		}
151	
152		var s state
153		dec := json.NewDecoder(bytes.NewReader(data))
154		if err := dec.Decode(&s); err != nil {
155			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
156		}
157		// 拒绝尾部多余内容，避免静默吞掉异常数据。
158		if dec.More() {
159			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
160		}
161		if err := s.validate(); err != nil {
162			return nil, fmt.Errorf("数据文件已损坏: %w", err)
163		}
164		// 旧版本数据文件没有 adjustments/payments/next_seq 字段：视为零调整、零实收。
165		if s.Adjustments == nil {
166			s.Adjustments = map[string]*adjustment{}
167		}
168		if s.Payments == nil {
169			s.Payments = map[string]*payment{}
170		}
171		s.path = p
172		return &s, nil
173	}
174	
175	func newState(p string) *state {
176		return &state{
177			Version:     stateVersion,
178			Customers:   map[string]*customer{},
179			Usage:       map[string]*usageRecord{},
180			Bills:       map[string]*bill{},
181			Adjustments: map[string]*adjustment{},
182			Payments:    map[string]*payment{},
183			path:        p,
184		}
185	}
186	
187	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
188	func (s *state) validate() error {
189		if s.Version != stateVersion {
190			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
191		}
192		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
193			return errors.New("缺少必要的数据节")
194		}
195		for id, c := range s.Customers {
196			if c == nil {
197				return fmt.Errorf("客户 %q 的数据为空", id)
198			}
199			if c.ID != id {
200				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
201			}
202			if c.ID == "" || c.Name == "" {
203				return fmt.Errorf("客户 %q 的标识或名称为空", id)
204			}
205			if c.Price < 0 {
206				return fmt.Errorf("客户 %q 单价为负", id)
207			}
208		}
209		for id, u := range s.Usage {
210			if u == nil {
211				return fmt.Errorf("用量 %q 的数据为空", id)
212			}
213			if u.ID != id {
214				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
215			}
216			if u.ID == "" {
217				return errors.New("存在空的用量标识")
218			}
219			if _, ok := s.Customers[u.CustomerID]; !ok {
220				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
221			}
222			if u.Quantity <= 0 {
223				return fmt.Errorf("用量 %q 的数量非正", u.ID)
224			}
225			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
226				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
227			}
228		}
229		for key, b := range s.Bills {
230			if b == nil {
231				return fmt.Errorf("账单 %q 的数据为空", key)
232			}
233			if billKey(b.CustomerID, b.Month) != key {
234				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
235			}
236			if _, ok := s.Customers[b.CustomerID]; !ok {
237				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
238			}
239			if !validMonth(b.Month) {
240				return fmt.Errorf("账单 %q 的月份无效", key)
241			}
242			if len(b.Lines) == 0 {
243				return fmt.Errorf("账单 %q 没有明细", key)
244			}
245			var qty, fee int64
246			for _, ln := range b.Lines {
247				u, ok := s.Usage[ln.UsageID]
248				if !ok {
249					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
250				}
251				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
252					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
253				}
254				if !inMonth(u.Time, b.Month) {
255					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
256				}
257				var err error
258				qty, err = add64(qty, ln.Quantity)
259				if err != nil {
260					return fmt.Errorf("账单 %q 汇总数量溢出", key)
261				}
262				fee, err = add64(fee, ln.LineFee)
263				if err != nil {
264					return fmt.Errorf("账单 %q 汇总金额溢出", key)
265				}
266			}
267			if qty != b.TotalQty {
268				return fmt.Errorf("账单 %q 总数量与明细不符", key)
269			}
270			if fee != b.TotalFee {
271				return fmt.Errorf("账单 %q 总金额与明细不符", key)
272			}
273			c := s.Customers[b.CustomerID]
274			for _, ln := range b.Lines {
275				lf, err := mul64(ln.Quantity, c.Price)
276				if err != nil {
277					return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
278				}
279				if lf != ln.LineFee {
280					return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
281				}
282			}
283			if b.UnitPrice != c.Price {
284				return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
285			}
286			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
287			// 而已入账记录理应全部在明细中）。
288			for _, u := range s.Usage {
289				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
290					found := false
291					for _, ln := range b.Lines {
292						if ln.UsageID == u.ID {
293							found = true
294							break
295						}
296					}
297					if !found {
298						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
299					}
300				}
301			}
302		}
303	
304		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
305		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
306		// 允许同名，各自判重与撤销。
307		if s.NextSeq < 0 {
308			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
309		}
310		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
311		for id, a := range s.Adjustments {
312			if a == nil {
313				return fmt.Errorf("调整 %q 的数据为空", id)
314			}
315			if a.ID != id {
316				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
317			}
318			if a.ID == "" {
319				return errors.New("存在空的调整标识")
320			}
321			if a.Amount == 0 {
322				return fmt.Errorf("调整 %q 的金额为零", id)
323			}
324			if strings.TrimSpace(a.Reason) == "" {
325				return fmt.Errorf("调整 %q 的原因为空", id)
326			}
327			if !validMonth(a.Month) {
328				return fmt.Errorf("调整 %q 的月份无效", id)
329			}
330			if _, ok := s.Customers[a.CustomerID]; !ok {
331				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
332			}
333			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
334				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
335			}
336			if a.Seq < 1 || a.Seq > s.NextSeq {
337				return fmt.Errorf("调整 %q 的操作序号越界", id)
338			}
339			if prev, dup := seenSeq[a.Seq]; dup {
340				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
341			}
342			seenSeq[a.Seq] = "调整 " + id
343			if a.Revoked {
344				if strings.TrimSpace(a.RevokeReason) == "" {
345					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
346				}
347				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
348					return fmt.Errorf("调整 %q 的撤销序号越界", id)
349				}
350				if prev, dup := seenSeq[a.RevokeSeq]; dup {
351					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
352				}
353				seenSeq[a.RevokeSeq] = "撤销调整 " + id
354			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
355				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
356			}
357		}
358		for id, p := range s.Payments {
359			if p == nil {
360				return fmt.Errorf("收款 %q 的数据为空", id)
361			}
362			if p.ID != id {
363				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
364			}
365			if p.ID == "" {
366				return errors.New("存在空的收款标识")
367			}
368			if p.Total <= 0 {
369				return fmt.Errorf("收款 %q 的总额不是正整数", id)
370			}
371			if strings.TrimSpace(p.Note) == "" {
372				return fmt.Errorf("收款 %q 的备注为空", id)
373			}
374			if _, ok := s.Customers[p.CustomerID]; !ok {
375				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
376			}
377			if len(p.Allocations) == 0 {
378				return fmt.Errorf("收款 %q 没有分配", id)
379			}
380			seenMonths := make(map[string]bool)
381			var sum int64
382			for _, al := range p.Allocations {
383				if !validMonth(al.Month) {
384					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
385				}
386				if seenMonths[al.Month] {
387					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
388				}
389				seenMonths[al.Month] = true
390				if al.Amount <= 0 {
391					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
392				}
393				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
394					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
395				}
396				var err error
397				sum, err = add64(sum, al.Amount)
398				if err != nil {
399					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
400				}
401			}
402			if sum != p.Total {
403				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
404			}
405			if p.Seq < 1 || p.Seq > s.NextSeq {
406				return fmt.Errorf("收款 %q 的操作序号越界", id)
407			}
408			if prev, dup := seenSeq[p.Seq]; dup {
409				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
410			}
411			seenSeq[p.Seq] = "收款 " + id
412			if p.Revoked {
413				if strings.TrimSpace(p.RevokeReason) == "" {
414					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
415				}
416				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
417					return fmt.Errorf("收款 %q 的撤销序号越界", id)
418				}
419				if prev, dup := seenSeq[p.RevokeSeq]; dup {
420					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
421				}
422				seenSeq[p.RevokeSeq] = "撤销收款 " + id
423			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
424				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
425			}
426		}
427		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
428		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款在该月的分配之和）
429		// 必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
430		for key, b := range s.Bills {
431			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
432			if err != nil {
433				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
434			}
435			received, err := paymentReceived(paymentsFor(s, b.CustomerID, b.Month), b.Month)
436			if err != nil {
437				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
438			}
439			if received > payable {
440				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
441			}
442		}
443		return nil
444	}
445	
446	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
447	// 只有完整保存成功后调用方才会向用户报告成功。
448	func (s *state) save() error {
449		if err := s.validate(); err != nil {
450			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
451		}
452		data, err := json.MarshalIndent(s, "", "  ")
453		if err != nil {
454			return fmt.Errorf("序列化数据失败: %w", err)
455		}
456		data = append(data, '\n')
457	
458		tmp := s.path + ".tmp"
459		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
460		if err != nil {
461			return fmt.Errorf("写入临时数据文件失败: %w", err)
462		}
463		if _, err := f.Write(data); err != nil {
464			f.Close()
465			os.Remove(tmp)
466			return fmt.Errorf("写入临时数据文件失败: %w", err)
467		}
468		if err := f.Sync(); err != nil {
469			f.Close()
470			os.Remove(tmp)
471			return fmt.Errorf("同步数据文件失败: %w", err)
472		}
473		if err := f.Close(); err != nil {
474			os.Remove(tmp)
475			return fmt.Errorf("关闭数据文件失败: %w", err)
476		}
477		if err := os.Rename(tmp, s.path); err != nil {
478			os.Remove(tmp)
479			return fmt.Errorf("替换数据文件失败: %w", err)
480		}
481		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
482			dir.Sync()
483			dir.Close()
484		}
485		return nil
486	}
487	
488	func billKey(customerID, month string) string {
489		return customerID + "|" + month
490	}
491	
492	// sealed 报告某客户的指定月份是否已封账。
493	func (s *state) sealed(customerID, month string) bool {
494		_, ok := s.Bills[billKey(customerID, month)]
495		return ok
496	}
497	
498	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
499	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
500		var list []*adjustment
501		for _, a := range s.Adjustments {
502			if a.CustomerID == customerID && a.Month == month {
503				list = append(list, a)
504			}
505		}
506		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
507		return list
508	}
509	
510	// paymentsFor 返回分配到某客户某月账单的全部收款，按操作序号升序。
511	func paymentsFor(s *state, customerID, month string) []*payment {
512		var list []*payment
513		for _, p := range s.Payments {
514			if p.CustomerID == customerID && p.amountFor(month) > 0 {
515				list = append(list, p)
516			}
517		}
518		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
519		return list
520	}
521	
522	// paymentReceived 返回全部未撤销收款在指定月份的分配之和。各笔分配均为
523	// 正整数，用非负 64 位加法累加，溢出时返回错误。
524	func paymentReceived(pays []*payment, month string) (int64, error) {
525		var received int64
526		for _, p := range pays {
527			if !p.Revoked {
528				var err error
529				received, err = add64(received, p.amountFor(month))
530				if err != nil {
531					return 0, err
532				}
533			}
534		}
535		return received, nil
536	}
537	
538	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
539	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
540	
541	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
542	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
543	// [0, 有符号 64 位最大值] 内，全程整数运算。
544	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
545		var amounts []int64
546		for _, a := range adjs {
547			if !a.Revoked {
548				amounts = append(amounts, a.Amount)
549			}
550		}
551		net, err = sumSigned64(amounts...)
552		if err != nil {
553			return 0, 0, err
554		}
555		payable, err = addSigned64(b.TotalFee, net)
556		if err != nil {
557			return 0, 0, err
558		}
559		if payable < 0 {
560			return 0, 0, errPayableOutOfRange
561		}
562		return net, payable, nil
563	}
564

