196		var problems []string
197		problems = append(problems, parseErrs...)
198	
199		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
200		var ordered []*parsedRow
201		newCount, dupCount := 0, 0
202	
203		for _, r := range rows {
