210			if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
211				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
212				continue
213			}
214	
215			// 去重判定同时对“库中已有”和“本文件内已出现”生效。
216			var existing *usageRecord
217			if inStore, ok := s.Usage[r.rec.ID]; ok {
218				existing = inStore
219			} else if inBatch, ok := accepted[r.rec.ID]; ok {
220				existing = &inBatch.rec
221			}
222	
223			if existing != nil {
224				if !sameUsage(existing, &r.rec, r.t) {
