262	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
263	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
264		cr := csv.NewReader(r)
265		cr.FieldsPerRecord = 4
266		cr.TrimLeadingSpace = true
267	
268		header, err := cr.Read()
269		if err == io.EOF {
270			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
271		}
272		if err != nil {
273			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
274		}
275		for i := range header {
276			header[i] = strings.TrimSpace(header[i])
277		}
278		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
279			header[2] != "time" || header[3] != "quantity" {
280			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
281		}
282	
283		var rows []*parsedRow
284		var problems []string
285		line := 1
286		for {
287			rec, err := cr.Read()
288			if err == io.EOF {
289				break
290			}
291			line++
292			if err != nil {
293				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
294				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
295					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
296					break
297				}
298				continue
299			}
300			for i := range rec {
301				rec[i] = strings.TrimSpace(rec[i])
302			}
303	
304			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
305			if id == "" {
306				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
307				continue
308			}
309			if custID == "" {
310				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
311				continue
312			}
313			t, err := time.Parse(time.RFC3339, ts)
314			if err != nil {
315				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
316				continue
317			}
318			qty, err := strconv.ParseInt(qtyText, 10, 64)
319			if err != nil {
320				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
321				continue
322			}
323			if qty <= 0 {
324				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
325				continue
326			}
327	
328			rows = append(rows, &parsedRow{
329				line: line,
330				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
331				t:    t,
332			})
333		}
334		return rows, problems
335	}
336	
337	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
338	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
339	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
340		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
341			return false
342		}
343		et, err := time.Parse(time.RFC3339, existing.Time)
344		if err != nil {
345			return existing.Time == candidate.Time
346		}
347		return et.Equal(candidateT)
348	}
349	
350	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
351	func validMonth(m string) bool {
352		t, err := time.Parse("2006-01", m)
353		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
354			return false
355		}
356		return true
357	}
358	
359	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
360	func inMonth(rfc3339, month string) bool {
361		t, err := time.Parse(time.RFC3339, rfc3339)
362		if err != nil {
363			return false
364		}
365		return t.UTC().Format("2006-01") == month
366	}
367	
368	func cmdBillSettle(dir, customerID, month string) error {
369		if !validMonth(month) {
370			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
371		}
372		s, err := loadStore(dir)
373		if err != nil {
374			return err
375		}
376		cust, ok := s.Customers[customerID]
377		if !ok {
378			return fmt.Errorf("客户标识 %q 不存在", customerID)
379		}
380	
381		key := billKey(customerID, month)
382		if existing, ok := s.Bills[key]; ok {
383			// 幂等：同一客户同一月份重复结算，直接返回原账单，
384			// 不重新计费、不产生新账单或调整、不落盘。
385			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
386			printBill(existing, cust, adjustmentsFor(s, customerID, month), paymentsFor(s, customerID, month))
387			return nil
388		}
389	
390		// 归集该客户 UTC 自然月内的全部用量，区间为左闭右开 [月初, 下月初)。
391		var inMonthRecs []*usageRecord
392		for _, u := range s.Usage {
393			if u.CustomerID == customerID && inMonth(u.Time, month) {
394				inMonthRecs = append(inMonthRecs, u)
395			}
396		}
397		if len(inMonthRecs) == 0 {
398			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
399		}
400		sortByInstant(inMonthRecs)
401	
402		lines := make([]billLine, 0, len(inMonthRecs))
403		var totalQty, totalFee int64
404		for _, u := range inMonthRecs {
405			lineFee, err := mul64(u.Quantity, cust.Price)
406			if err != nil {
407				return fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出，拒绝结算且不封账", u.ID, u.Quantity, cust.Price)
408			}
409			totalQty, err = add64(totalQty, u.Quantity)
410			if err != nil {
411				return fmt.Errorf("汇总数量溢出有符号 64 位整数范围，拒绝结算且不封账")
412			}
413			totalFee, err = add64(totalFee, lineFee)
414			if err != nil {
415				return fmt.Errorf("汇总金额溢出有符号 64 位整数范围，拒绝结算且不封账")
416			}
417			lines = append(lines, billLine{
418				UsageID:  u.ID,
419				Time:     u.Time,
420				Quantity: u.Quantity,
421				LineFee:  lineFee,
422			})
423		}
424	
425		b := &bill{
426			ID:         stableBillID(customerID, month),
427			CustomerID: customerID,
428			Month:      month,
429			TotalQty:   totalQty,
430			UnitPrice:  cust.Price,
431			TotalFee:   totalFee,
432			Lines:      lines,
433			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
434		}
435		s.Bills[key] = b
436	
437		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
438		if err := s.save(); err != nil {
439			delete(s.Bills, key)
440			return err
441		}
442		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
443		printBill(b, cust, nil, nil)
444		return nil
445	}
