467	func sortByInstant(us []*usageRecord) {
468		// 入参时间均已在载入/导入时校验为 RFC3339。
469		sort.Slice(us, func(i, j int) bool {
470			ti, _ := time.Parse(time.RFC3339, us[i].Time)
471			tj, _ := time.Parse(time.RFC3339, us[j].Time)
472			ui, uj := ti.UTC(), tj.UTC()
473			if !ui.Equal(uj) {
474				return ui.Before(uj)
475			}
476			return us[i].ID < us[j].ID
477		})
478	}
