486	func printBill(b *bill, cust *customer, adjs []*adjustment, pays []*payment) {
487		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
488		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
489		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
490		fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
491		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
492		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
493		// 数据在载入时已校验一致，此处计算不会出错。
494		net, payable, _ := billTotals(b, adjs)
495		received, _ := paymentReceived(pays, b.Month)
496		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
497		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
498		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
499		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
