504				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
505		}
506		if len(adjs) == 0 {
507			fmt.Fprintln(stdout, "调整与撤销历史：无")
508		} else {
509			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
510			for i, ev := range historyEvents(adjs) {
511				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
512			}
513		}
514		if len(pays) == 0 {
515			fmt.Fprintln(stdout, "收款与撤销历史：无")
516		} else {
517			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
518			for i, ev := range paymentHistoryEvents(pays, b.Month) {
519				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
520			}
521		}
522	}
