524	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
525	func historyEvents(adjs []*adjustment) []string {
526		type event struct {
527			seq  int64
528			text string
529		}
530		var events []event
531		for _, a := range adjs {
532			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
533				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
534			if a.Revoked {
535				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
536					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
537			}
538		}
539		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
540		out := make([]string, len(events))
541		for i, ev := range events {
542			out[i] = ev.text
543		}
544		return out
545	}
