561	// paymentHistoryEvents 把收款登记与撤销展开为按操作序号排序的可读历史条目；
562	// month 为当前展示账单所在月份，用于给出该收款在本账单的分配。
563	func paymentHistoryEvents(pays []*payment, month string) []string {
564		type event struct {
565			seq  int64
566			text string
567		}
568		var events []event
569		for _, p := range pays {
570			alloc := p.amountFor(month)
571			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
572				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
573			if p.Revoked {
574				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
575					p.ID, p.RevokeReason, p.ID, p.Total, alloc)})
576			}
577		}
578		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
579		out := make([]string, len(events))
580		for i, ev := range events {
581			out[i] = ev.text
582		}
583		return out
584	}
