593	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
594	func parseAmount(text string) (int64, error) {
595		text = strings.TrimSpace(text)
596		amount, err := strconv.ParseInt(text, 10, 64)
597		if err != nil {
598			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
599		}
600		if amount == 0 {
601			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
602		}
603		return amount, nil
604	}
