606	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
607		if !validMonth(month) {
608			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
609		}
610		if strings.TrimSpace(adjID) == "" {
611			return fmt.Errorf("调整标识不能为空")
612		}
613		amount, err := parseAmount(amountText)
614		if err != nil {
615			return err
616		}
617		if strings.TrimSpace(reason) == "" {
618			return fmt.Errorf("调整原因不能为空")
619		}
620	
621		s, err := loadStore(dir)
622		if err != nil {
623			return err
624		}
625		if _, ok := s.Customers[customerID]; !ok {
626			return fmt.Errorf("客户标识 %q 不存在", customerID)
627		}
628		b, ok := s.Bills[billKey(customerID, month)]
629		if !ok {
630			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
631		}
632	
633		if existing, ok := s.Adjustments[adjID]; ok {
634			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
635			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
636			if existing.CustomerID == customerID && existing.Month == month &&
637				existing.Amount == amount && existing.Reason == reason {
638				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
639				printAdjustment(existing, s)
640				return nil
641			}
642			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
643				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
644		}
645	
646		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
647		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
648		// 不占用该调整标识。
649		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
650		if err != nil {
651			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
652		}
653		received, err := paymentReceived(paymentsFor(s, customerID, month), month)
654		if err != nil {
655			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
656		}
657		newPayable, err := addSigned64(payable, amount)
658		if err != nil {
659			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
660		}
661		if newPayable < 0 {
662			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
663		}
664		if newPayable < received {
665			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
666				newPayable, received, payable, amount)
667		}
668	
669		a := &adjustment{
670			ID:         adjID,
671			CustomerID: customerID,
672			Month:      month,
673			Amount:     amount,
674			Reason:     reason,
675			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
676		}
677		s.NextSeq++
678		a.Seq = s.NextSeq
679		s.Adjustments[adjID] = a
680	
681		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
682		// 该调整标识不被占用。
683		if err := s.save(); err != nil {
684			delete(s.Adjustments, adjID)
685			s.NextSeq--
686			return err
687		}
688		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
689			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
690		printAdjustment(a, s)
691		return nil
692	}
