694	func cmdBillRevoke(dir, adjID, reason string) error {
695		if strings.TrimSpace(adjID) == "" {
696			return fmt.Errorf("调整标识不能为空")
697		}
698		if strings.TrimSpace(reason) == "" {
699			return fmt.Errorf("撤销原因不能为空")
700		}
701	
702		s, err := loadStore(dir)
703		if err != nil {
704			return err
705		}
706		a, ok := s.Adjustments[adjID]
707		if !ok {
708			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
709		}
710	
711		if a.Revoked {
712			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
713			// 改用其他原因则拒绝。
714			if a.RevokeReason == reason {
715				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
716				printAdjustment(a, s)
717				return nil
718			}
719			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
720		}
721	
722		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
723		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
724		// 改变余额后重试。
725		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
726		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
727		if err != nil {
728			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
729		}
730		received, err := paymentReceived(paymentsFor(s, a.CustomerID, a.Month), a.Month)
731		if err != nil {
732			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
733		}
734		neg, err := neg64(a.Amount)
735		if err != nil {
736			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
737		}
738		newPayable, err := addSigned64(payable, neg)
739		if err != nil {
740			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
741				payable, a.Amount)
742		}
743		if newPayable < 0 {
744			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
745				newPayable, payable, a.Amount)
746		}
747		if newPayable < received {
748			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
749				newPayable, received, payable, a.Amount)
750		}
751	
752		a.Revoked = true
753		a.RevokeReason = reason
754		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
755		s.NextSeq++
756		a.RevokeSeq = s.NextSeq
757	
758		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
759		if err := s.save(); err != nil {
760			a.Revoked = false
761			a.RevokeReason = ""
762			a.RevokedAt = ""
763			a.RevokeSeq = 0
764			s.NextSeq--
765			return err
766		}
767		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
768			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
769		printAdjustment(a, s)
770		return nil
771	}
