773	// printAdjustment 输出单笔调整记录及其当前状态；payable 取自当前库状态。
774	func printAdjustment(a *adjustment, s *state) {
775		b := s.Bills[billKey(a.CustomerID, a.Month)]
776		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
777		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
778		fmt.Fprintf(stdout, "客户：%s\n", a.CustomerID)
779		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
780		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
781		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
782		if a.Revoked {
783			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", a.RevokeReason)
784		} else {
785			fmt.Fprintf(stdout, "当前状态：生效中\n")
786		}
787		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
788	}
