790	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
791	func parsePositiveAmount(text string) (int64, error) {
792		text = strings.TrimSpace(text)
793		amount, err := strconv.ParseInt(text, 10, 64)
794		if err != nil {
795			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
796		}
797		if amount <= 0 {
798			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
799		}
800		return amount, nil
801	}
