803	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
804		if !validMonth(month) {
805			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
806		}
807		amount, err := parsePositiveAmount(amountText)
808		if err != nil {
809			return err
810		}
811		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
812		return registerPayment(dir, customerID, payID, amount, note,
813			[]paymentAllocation{{Month: month, Amount: amount}})
