816	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
817		total, err := parsePositiveAmount(totalText)
818		if err != nil {
819			return err
820		}
821		allocs, err := parseAllocations(allocArgs)
822		if err != nil {
823			return err
824		}
825		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
826		var sum int64
827		for _, al := range allocs {
828			sum, err = add64(sum, al.Amount)
829			if err != nil {
830				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
831			}
832		}
833		if sum != total {
834			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
835		}
836		return registerPayment(dir, customerID, payID, total, note, allocs)
837	}
