839	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
840	// 月份不得重复，每项金额为正整数分。
841	func parseAllocations(args []string) ([]paymentAllocation, error) {
842		if len(args) == 0 {
843			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
844		}
845		seen := make(map[string]bool)
846		allocs := make([]paymentAllocation, 0, len(args))
847		for _, arg := range args {
848			parts := strings.Split(arg, ":")
849			if len(parts) != 2 {
850				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
851			}
852			month := strings.TrimSpace(parts[0])
853			if !validMonth(month) {
854				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
855			}
856			if seen[month] {
857				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
858			}
859			seen[month] = true
860			amount, err := parsePositiveAmount(parts[1])
861			if err != nil {
862				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
863			}
864			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
865		}
866		return allocs, nil
867	}
