869	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
870	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
871	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
872		if strings.TrimSpace(payID) == "" {
873			return fmt.Errorf("收款标识不能为空")
874		}
875		if strings.TrimSpace(note) == "" {
876			return fmt.Errorf("收款备注不能为空")
877		}
878		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
879		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
880	
881		s, err := loadStore(dir)
882		if err != nil {
883			return err
884		}
885		if _, ok := s.Customers[customerID]; !ok {
886			return fmt.Errorf("客户标识 %q 不存在", customerID)
887		}
888		for _, al := range allocs {
889			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
890				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
891			}
892		}
893	
894		if existing, ok := s.Payments[payID]; ok {
895			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
896			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
897			// 已撤销的重放仍返回已撤销状态，不恢复实收。
898			if samePaymentContent(existing, customerID, total, note, allocs) {
899				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
900				printPayment(existing, s)
901				return nil
902			}
903			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
904				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
905		}
906	
907		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
908		for _, al := range allocs {
909			b := s.Bills[billKey(customerID, al.Month)]
910			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
911			if err != nil {
912				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
913			}
914			received, err := paymentReceived(paymentsFor(s, customerID, al.Month), al.Month)
915			if err != nil {
916				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
917			}
918			if payable == 0 {
919				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
920			}
921			if al.Amount > payable-received {
922				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
923					al.Amount, payable-received, customerID, al.Month, payable, received)
924			}
925		}
926	
927		p := &payment{
928			ID:          payID,
929			CustomerID:  customerID,
930			Total:       total,
931			Note:        note,
932			Allocations: allocs,
933			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
934		}
935		s.NextSeq++
936		p.Seq = s.NextSeq
937		s.Payments[payID] = p
938	
939		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
940		// 一切不生效，该收款标识不被占用。
941		if err := s.save(); err != nil {
942			delete(s.Payments, payID)
943			s.NextSeq--
944			return err
945		}
946		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
947		printAllocationBalances(s, p)
948		fmt.Fprintln(stdout)
949		printPayment(p, s)
950		return nil
951	}
952	
953	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
954	// 内容相同；分配顺序不影响身份。
955	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
956		if p.CustomerID != customerID || p.Total != total || p.Note != note {
957			return false
958		}
959		if len(p.Allocations) != len(allocs) {
960			return false
961		}
962		for _, al := range allocs {
963			if p.amountFor(al.Month) != al.Amount {
964				return false
965			}
966		}
967		return true
968	}
