970	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
971	func formatAllocations(allocs []paymentAllocation) string {
972		parts := make([]string, len(allocs))
973		for i, al := range allocs {
974			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
975		}
976		return strings.Join(parts, ",")
977	}
