979	// printAllocationBalances 输出该收款每个分配月份当前的实收与未收余额。
980	func printAllocationBalances(s *state, p *payment) {
981		for _, al := range p.Allocations {
982			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
983			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
984			received, _ := paymentReceived(paymentsFor(s, p.CustomerID, al.Month), al.Month)
985			fmt.Fprintf(stdout, "  月份 %s：分配 %d 分，实收 %d 分（%s），未收余额 %d 分（%s）\n",
986				al.Month, al.Amount, received, moneyFen(received), payable-received, moneyFen(payable-received))
987		}
988	}
