990	func cmdBillUnpay(dir, payID, reason string) error {
991		if strings.TrimSpace(payID) == "" {
992			return fmt.Errorf("收款标识不能为空")
993		}
994		if strings.TrimSpace(reason) == "" {
995			return fmt.Errorf("撤销原因不能为空")
996		}
997	
998		s, err := loadStore(dir)
999		if err != nil {
1000			return err
1001		}
1002		p, ok := s.Payments[payID]
1003		if !ok {
1004			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1005		}
1006	
1007		if p.Revoked {
1008			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1009			// 改用其他原因则拒绝。
1010			if p.RevokeReason == reason {
1011				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1012				printPayment(p, s)
1013				return nil
1014			}
1015			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1016		}
1017	
1018		// 撤销整笔生效：取消该笔在全部分配月份上的实收，不接受部分撤销；
1019		// 不改变应付、其他收款或调整，原收款、分配与撤销原因永久保留。
1020		p.Revoked = true
1021		p.RevokeReason = reason
1022		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1023		s.NextSeq++
1024		p.RevokeSeq = s.NextSeq
1025	
1026		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1027		if err := s.save(); err != nil {
1028			p.Revoked = false
1029			p.RevokeReason = ""
1030			p.RevokedAt = ""
1031			p.RevokeSeq = 0
1032			s.NextSeq--
1033			return err
1034		}
1035		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s）：\n", payID, p.Total, moneyFen(p.Total))
1036		printAllocationBalances(s, p)
1037		fmt.Fprintln(stdout)
1038		printPayment(p, s)
1039		return nil
1040	}
