1050			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1051		} else {
1052			fmt.Fprintf(stdout, "当前状态：实收中\n")
1053		}
1054		fmt.Fprintln(stdout, "分配明细：")
1055		for i, al := range p.Allocations {
1056			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1057			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1058			received, _ := paymentReceived(paymentsFor(s, p.CustomerID, al.Month), al.Month)
1059			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1060				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1061		}
1062	}
