1064	// --- 账后对账流水 ---
1065	
1066	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款
1067	// 或撤销收款。事件按全局操作序号升序回放；撤销在其发生序号抵消对应原操作，
1068	// 已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件。
1069	type ledgerEvent struct {
1070		seq           int64  // 全局操作序号（调整/收款及其撤销共用）
1071		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 撤销收款
1072		refID         string // 原记录标识（调整标识或收款标识）
1073		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1074		deltaReceived int64  // 对实收的影响（分，带符号）
1075		note          string // 原因（调整类）或备注（收款类）
1076		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1077		payTotal      int64  // 收款类事件：汇款总额
1078		payAlloc      int64  // 收款类事件：本账单分配
1079		afterPayable  int64  // 事件后的应付（回放时填充）
1080		afterReceived int64  // 事件后的实收（回放时填充）
1081	}
1082	
1083	// billLedger 把目标账单的调整、调整撤销、收款与收款撤销合并为一条按操作
1084	// 序号升序的流水，并以原总金额为初始应付、零实收为起点逐步回放，填充每个
1085	// 事件之后的三项余额。回放覆盖完整流水（不受查询截止序号限制）：序号重复、
1086	// 撤销先于原操作，或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位
1087	// 最大值，都视为数据异常并拒绝——只检查最终余额会放过中间越界的存档。
1088	// 只读：不修改库、不占用序号、不新增记录。
1089	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1090		var events []ledgerEvent
1091		for _, a := range s.Adjustments {
1092			if a.CustomerID != b.CustomerID || a.Month != b.Month {
1093				continue
1094			}
1095			events = append(events, ledgerEvent{
1096				seq: a.Seq, kind: "调整", refID: a.ID,
1097				deltaPayable: a.Amount, note: a.Reason,
1098			})
1099			if a.Revoked {
1100				neg, err := neg64(a.Amount)
1101				if err != nil {
1102					return nil, fmt.Errorf("调整 %q 的金额 %d 分无法抵消（越界），数据异常，拒绝输出流水", a.ID, a.Amount)
1103				}
1104				events = append(events, ledgerEvent{
1105					seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
1106					deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
1107				})
1108			}
1109		}
1110		for _, p := range s.Payments {
1111			if p.CustomerID != b.CustomerID {
1112				continue
1113			}
1114			// 多月汇款只以本账单分配改变实收；整笔撤销在同一序号取消该分配。
1115			alloc := p.amountFor(b.Month)
1116			if alloc <= 0 {
1117				continue
1118			}
1119			events = append(events, ledgerEvent{
1120				seq: p.Seq, kind: "收款", refID: p.ID,
1121				deltaReceived: alloc, note: p.Note,
1122				payTotal: p.Total, payAlloc: alloc,
1123			})
1124			if p.Revoked {
1125				events = append(events, ledgerEvent{
1126					seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
1127					deltaReceived: -alloc, note: p.RevokeReason, linkSeq: p.Seq,
1128					payTotal: p.Total, payAlloc: alloc,
1129				})
1130			}
1131		}
1132		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
1133	
1134		// 逐步回放并核验：只把每个事件的金额影响加到运行余额上，不对发生额
1135		// 做累计求和，因此累计补收/收款发生额超过 64 位上限但每步余额合法时
1136		// 仍能成功。
1137		payable := b.TotalFee
1138		var received int64
1139		seen := make(map[int64]string, len(events))
1140		for i := range events {
1141			ev := &events[i]
1142			desc := ev.kind + " " + ev.refID
1143			if prev, dup := seen[ev.seq]; dup {
1144				return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常，拒绝输出流水", ev.seq, prev, desc)
1145			}
1146			seen[ev.seq] = desc
1147			if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
1148				return nil, fmt.Errorf("%s 的撤销序号 %d 不晚于原操作序号 %d，数据异常，拒绝输出流水", desc, ev.seq, ev.linkSeq)
1149			}
1150			var err error
1151			if payable, err = addSigned64(payable, ev.deltaPayable); err != nil {
1152				return nil, fmt.Errorf("序号 %d（%s）之后应付越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1153			}
1154			if received, err = addSigned64(received, ev.deltaReceived); err != nil {
1155				return nil, fmt.Errorf("序号 %d（%s）之后实收越出有符号 64 位整数范围，数据异常，拒绝输出流水", ev.seq, desc)
1156			}
1157			if payable < 0 {
1158				return nil, fmt.Errorf("序号 %d（%s）之后应付为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, payable)
1159			}
1160			if received < 0 {
1161				return nil, fmt.Errorf("序号 %d（%s）之后实收为 %d 分（小于 0），数据异常，拒绝输出流水", ev.seq, desc, received)
1162			}
1163			if received > payable {
1164				return nil, fmt.Errorf("序号 %d（%s）之后实收 %d 分超过应付 %d 分，数据异常，拒绝输出流水", ev.seq, desc, received, payable)
1165			}
1166			ev.afterPayable = payable
1167			ev.afterReceived = received
1168		}
1169		return events, nil
1170	}
