1172	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1173		if !validMonth(month) {
1174			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1175		}
1176		s, err := loadStore(dir)
1177		if err != nil {
1178			return err
1179		}
1180		cust, ok := s.Customers[customerID]
1181		if !ok {
1182			return fmt.Errorf("客户标识 %q 不存在", customerID)
1183		}
1184		b, ok := s.Bills[billKey(customerID, month)]
1185		if !ok {
1186			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1187		}
1188	
1189		// 截止序号使用调整/收款及其撤销共用的已保存全局序号：省略表示最新，
1190		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1191		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1192		cutoff := s.NextSeq
1193		cutoffDesc := "省略，按最新"
1194		if hasCutoff {
1195			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1196			if perr != nil {
1197				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1198			}
1199			if v < 0 {
1200				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1201			}
1202			if v > s.NextSeq {
1203				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1204			}
1205			cutoff = v
1206			cutoffDesc = "指定"
1207		}
1208	
1209		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1210		// 拒绝，不输出部分正常的报告。
1211		events, err := billLedger(s, b)
1212		if err != nil {
1213			return err
1214		}
1215		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1216		return nil
1217	}
1218	
1219	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1220		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1221		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1222		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1223		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1224		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1225		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1226		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1227			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1228	
1229		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1230		payable, received := b.TotalFee, int64(0)
1231		var shown []ledgerEvent
1232		for _, ev := range events {
1233			if ev.seq > cutoff {
1234				continue
1235			}
1236			shown = append(shown, ev)
1237			payable, received = ev.afterPayable, ev.afterReceived
1238		}
1239		if len(shown) == 0 {
1240			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1241		} else {
1242			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1243			for i, ev := range shown {
1244				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1245			}
1246		}
1247		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1248			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1249	}
1250	
1251	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1252	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1253	// 说明汇款总额与本账单分配。
1254	func formatLedgerEvent(ev ledgerEvent) string {
1255		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1256			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1257		switch ev.kind {
1258		case "调整":
1259			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1260				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1261		case "撤销调整":
1262			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1263				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1264		case "收款":
1265			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1266				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1267		default: // 撤销收款
1268			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1269				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1270		}
1271	}
1272

