15	// mul64 返回 a*b，溢出时返回错误。a、b 均非负。
16	func mul64(a, b int64) (int64, error) {
17		if a < 0 || b < 0 {
18			return 0, errOverflow
19		}
20		if a == 0 || b == 0 {
21			return 0, nil
22		}
23		if a > math.MaxInt64/b {
24			return 0, errOverflow
25		}
26		return a * b, nil
27	}
28	
29	// add64 返回 a+b，溢出时返回错误。a、b 均非负。
30	func add64(a, b int64) (int64, error) {
31		if a < 0 || b < 0 || a > math.MaxInt64-b {
32			return 0, errOverflow
33		}
34		return a + b, nil
35	}
36	
37	// addSigned64 返回 a+b（允许负数），溢出时返回错误。
38	func addSigned64(a, b int64) (int64, error) {
39		if (b > 0 && a > math.MaxInt64-b) || (b < 0 && a < math.MinInt64-b) {
40			return 0, errOverflow
41		}
42		return a + b, nil
43	}
