	return list
}

// paymentInvolves 报告该收款是否曾涉及指定月份：首次登记分配或任一更正的
// 前/后分配包含该月。
func paymentInvolves(s *state, p *payment, month string) bool {
	if p.amountFor(month) > 0 {
		return true
	}
