	if !strings.Contains(oct, "实收：250 分") {
		t.Fatal(oct)
	}

	// 重放原收款返回当前状态：当前生效分配与完整更正历史，不恢复旧分配。
	out = h.mustRun("bill", "remit", "c1", "r1", "700", "汇款", "2026-10:300", "2026-09:400")
