1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID    string `json:"id"`
27		Name  string `json:"name"`
28		Price int64  `json:"price_fen"` // 固定单价，非负整数分，创建后不可修改
29	}
30	
31	type usageRecord struct {
32		ID         string `json:"id"`
33		CustomerID string `json:"customer_id"`
34		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
35		Quantity   int64  `json:"quantity"`
36	}
37	
38	type billLine struct {
39		UsageID  string `json:"usage_id"`
40		Time     string `json:"time"`
41		Quantity int64  `json:"quantity"`
42		LineFee  int64  `json:"line_fee_fen"`
43	}
44	
45	type bill struct {
46		ID         string     `json:"id"`
47		CustomerID string     `json:"customer_id"`
48		Month      string     `json:"month"` // YYYY-MM（UTC）
49		TotalQty   int64      `json:"total_quantity"`
50		UnitPrice  int64      `json:"unit_price_fen"`
51		TotalFee   int64      `json:"total_fee_fen"`
52		Lines      []billLine `json:"lines"`
53		CreatedAt  string     `json:"created_at"`
54	}
55	
56	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
57	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
58	type adjustment struct {
59		ID           string `json:"id"`
60		CustomerID   string `json:"customer_id"`
61		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
62		Amount       int64  `json:"amount_fen"`
63		Reason       string `json:"reason"`
64		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
65		CreatedAt    string `json:"created_at"`
66		Revoked      bool   `json:"revoked"`
67		RevokeReason string `json:"revoke_reason,omitempty"`
68		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
69		RevokedAt    string `json:"revoked_at,omitempty"`
70	}
71	
72	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
73	type paymentAllocation struct {
74		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
75		Amount int64  `json:"amount_fen"` // 正整数分
76	}
77	
78	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
79	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
80	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
81	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
82	type payment struct {
83		ID           string              `json:"id"`
84		CustomerID   string              `json:"customer_id"`
85		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
86		Note         string              `json:"note"`
87		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
88		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
89		CreatedAt    string              `json:"created_at"`
90		Revoked      bool                `json:"revoked"`
91		RevokeReason string              `json:"revoke_reason,omitempty"`
92		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
93		RevokedAt    string              `json:"revoked_at,omitempty"`
94	}
95	
96	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
97	// 读入时归一化为一项分配，之后一律按新格式写回。
98	func (p *payment) UnmarshalJSON(data []byte) error {
99		type plain payment // 去掉方法，避免递归
100		var raw struct {
101			plain
102			Month  string `json:"month"`      // 旧格式：所属账单月份
103			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
104		}
105		if err := json.Unmarshal(data, &raw); err != nil {
106			return err
107		}
108		*p = payment(raw.plain)
109		if len(p.Allocations) == 0 && raw.Month != "" {
110			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
111			p.Total = raw.Amount
112		}
113		return nil
114	}
115	
116	// amountFor 返回该收款在指定月份的首次登记分配金额；无分配时为 0。
117	// 当前生效分配（经更正后）请用 currentAmountFor。
118	func (p *payment) amountFor(month string) int64 {
119		for _, al := range p.Allocations {
120			if al.Month == month {
121				return al.Amount
122			}
123		}
124		return 0
125	}
126	
127	// correction 是对一笔未撤销收款的分配更正：以更正时生效的分配（From）为
128	// 起点，整笔替换为完整新分配（To）。收款的客户、总额、备注与首次登记分配
129	// 永远不变；记录一旦写入永不删除，可连续更正（后一次以前一次的结果为起点）。
130	type correction struct {
131		ID        string              `json:"id"`
132		PaymentID string              `json:"payment_id"` // 目标收款标识
133		Reason    string              `json:"reason"`
134		From      []paymentAllocation `json:"from"` // 更正前生效分配（快照，按月份升序）
135		To        []paymentAllocation `json:"to"`   // 更正后完整新分配（按月份升序）
136		Seq       int64               `json:"seq"`  // 全局递增操作序号（与调整/收款及其撤销共用）
137		CreatedAt string              `json:"created_at"`
138	}
139	
140	type state struct {
141		Version     int                     `json:"version"`
142		Customers   map[string]*customer    `json:"customers"`
143		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
144		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
145		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
146		Payments    map[string]*payment     `json:"payments"`    // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
147		Corrections map[string]*correction  `json:"corrections"` // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
148		NextSeq     int64                   `json:"next_seq"`    // 已分配的最大操作序号（调整/收款/更正及其撤销共用）
149		path        string                  `json:"-"`
150	}
151	
152	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
153	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
154	func loadStore(dir string) (*state, error) {
155		p := filepath.Join(dir, "state.json")
156		data, err := os.ReadFile(p)
157		if err != nil {
158			if errors.Is(err, os.ErrNotExist) {
159				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
160					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
161				}
162				return newState(p), nil
163			}
164			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
165		}
166	
167		var s state
168		dec := json.NewDecoder(bytes.NewReader(data))
169		if err := dec.Decode(&s); err != nil {
170			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
171		}
172		// 拒绝尾部多余内容，避免静默吞掉异常数据。
173		if dec.More() {
174			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
175		}
176		if err := s.validate(); err != nil {
177			return nil, fmt.Errorf("数据文件已损坏: %w", err)
178		}
179		// 旧版本数据文件没有 adjustments/payments/corrections/next_seq 字段：
180		// 视为零调整、零实收、零更正。
181		if s.Adjustments == nil {
182			s.Adjustments = map[string]*adjustment{}
183		}
184		if s.Payments == nil {
185			s.Payments = map[string]*payment{}
186		}
187		if s.Corrections == nil {
188			s.Corrections = map[string]*correction{}
189		}
190		s.path = p
191		return &s, nil
192	}
193	
194	func newState(p string) *state {
195		return &state{
196			Version:     stateVersion,
197			Customers:   map[string]*customer{},
198			Usage:       map[string]*usageRecord{},
199			Bills:       map[string]*bill{},
200			Adjustments: map[string]*adjustment{},
201			Payments:    map[string]*payment{},
202			Corrections: map[string]*correction{},
203			path:        p,
204		}
205	}
206	
207	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
208	func (s *state) validate() error {
209		if s.Version != stateVersion {
210			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
211		}
212		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
213			return errors.New("缺少必要的数据节")
214		}
215		for id, c := range s.Customers {
216			if c == nil {
217				return fmt.Errorf("客户 %q 的数据为空", id)
218			}
219			if c.ID != id {
220				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
221			}
222			if c.ID == "" || c.Name == "" {
223				return fmt.Errorf("客户 %q 的标识或名称为空", id)
224			}
225			if c.Price < 0 {
226				return fmt.Errorf("客户 %q 单价为负", id)
227			}
228		}
229		for id, u := range s.Usage {
230			if u == nil {
231				return fmt.Errorf("用量 %q 的数据为空", id)
232			}
233			if u.ID != id {
234				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
235			}
236			if u.ID == "" {
237				return errors.New("存在空的用量标识")
238			}
239			if _, ok := s.Customers[u.CustomerID]; !ok {
240				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
241			}
242			if u.Quantity <= 0 {
243				return fmt.Errorf("用量 %q 的数量非正", u.ID)
244			}

