16	// 用量导入文件（CSV，UTF-8，首行为固定表头，之后每行一条用量）：
17	//
18	//	usage_id,customer_id,time,quantity
19	//	u-001,cust-1,2026-09-15T10:00:00Z,100
20	//
21	//	usage_id   全局唯一用量标识，非空
22	//	customer_id 必须是已登记的客户标识
23	//	time       RFC3339 时间，如 2026-09-15T10:00:00Z 或 2026-09-15T18:00:00+08:00
24	//	quantity   正整数数量（有符号 64 位整数范围内）
25	const usageHeader = "usage_id,customer_id,time,quantity"
26	
27	// runCmd 解析并执行子命令。业务/用法错误通过 error 返回，由 main 统一
28	// 写入标准错误并以非零状态退出。
29	func runCmd(args []string, dataDir string) error {
30		switch args[0] {
31		case "customer":
32			if len(args) < 2 {
33				return usageError("缺少子命令，应为：customer add <标识> <名称> <单价分>")
34			}
35			switch args[1] {
36			case "add":
37				if len(args) != 5 {
38					return usageError("用法：customer add <标识> <名称> <单价分>")
39				}
40				return cmdCustomerAdd(dataDir, args[2], args[3], args[4])
41			default:
42				return usageError("未知 customer 子命令 %q；可用：add", args[1])
43			}
44	
45		case "usage":
46			if len(args) < 2 {
47				return usageError("缺少子命令，应为：usage import <文件>")
48			}
49			switch args[1] {
50			case "import":
51				if len(args) != 3 {
52					return usageError("用法：usage import <文件>（- 表示标准输入）")
53				}
54				return cmdUsageImport(dataDir, args[2])
55			default:
56				return usageError("未知 usage 子命令 %q；可用：import", args[1])
57			}
58	
59		case "bill":
60			if len(args) < 2 {
61				return usageError("缺少子命令，应为：bill settle|show|adjust|revoke|pay|remit|unpay|correct|ledger ...")
62			}
63			switch args[1] {
64			case "settle":
65				if len(args) != 4 {
66					return usageError("用法：bill settle <客户标识> <YYYY-MM>")
67				}
68				return cmdBillSettle(dataDir, args[2], args[3])
69			case "show":
70				if len(args) != 4 {
71					return usageError("用法：bill show <客户标识> <YYYY-MM>")
72				}
73				return cmdBillShow(dataDir, args[2], args[3])
74			case "adjust":
75				if len(args) != 7 {
76					return usageError("用法：bill adjust <客户标识> <YYYY-MM> <调整标识> <金额分> <原因>")
77				}
78				return cmdBillAdjust(dataDir, args[2], args[3], args[4], args[5], args[6])
79			case "revoke":
80				if len(args) != 4 {
81					return usageError("用法：bill revoke <调整标识> <原因>")
82				}
83				return cmdBillRevoke(dataDir, args[2], args[3])
84			case "pay":
85				if len(args) != 7 {
86					return usageError("用法：bill pay <客户标识> <YYYY-MM> <收款标识> <金额分> <备注>")
87				}
88				return cmdBillPay(dataDir, args[2], args[3], args[4], args[5], args[6])
89			case "remit":
90				if len(args) < 6 {
91					return usageError("用法：bill remit <客户标识> <收款标识> <总金额分> <备注> <YYYY-MM:金额分> [更多 月份:金额 ...]")
92				}
93				return cmdBillRemit(dataDir, args[2], args[3], args[4], args[5], args[6:])
94			case "unpay":
95				if len(args) != 4 {
96					return usageError("用法：bill unpay <收款标识> <原因>")
97				}
98				return cmdBillUnpay(dataDir, args[2], args[3])
99			case "correct":
100				if len(args) < 5 {
101					return usageError("用法：bill correct <收款标识> <更正标识> <原因> <YYYY-MM:金额分> [更多 月份:金额 ...]")
102				}
103				return cmdBillCorrect(dataDir, args[2], args[3], args[4], args[5:])
104			case "ledger":
105				if len(args) != 4 && len(args) != 5 {
106					return usageError("用法：bill ledger <客户标识> <YYYY-MM> [截止操作序号]")
107				}
108				cutoff, hasCutoff := "", false
109				if len(args) == 5 {
110					cutoff, hasCutoff = args[4], true
111				}
112				return cmdBillLedger(dataDir, args[2], args[3], cutoff, hasCutoff)
113			default:
114				return usageError("未知 bill 子命令 %q；可用：settle、show、adjust、revoke、pay、remit、unpay、correct、ledger", args[1])
115			}
116	
117		default:
118			return usageError("未知命令 %q；可用：customer、usage、bill", args[0])
119		}
120	}
121	
122	type usageErrorf string
123	
124	func (e usageErrorf) Error() string { return string(e) }
125	
126	func usageError(format string, a ...any) error {
127		return usageErrorf(fmt.Sprintf(format, a...))
128	}
