157	func parsePrice(text string) (int64, error) {
158		text = strings.TrimSpace(text)
159		price, err := strconv.ParseInt(text, 10, 64)
160		if err != nil {
161			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
162		}
163		if price < 0 {
164			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
165		}
